export default function folder({ root }) {
  if (typeof root !== "string" || !root.trim() || root.startsWith("YOUR_"))
    throw Error("Configure a dedicated backup folder ID");
  return {
    root,
    name: "Workflow Backups " + new Date().toISOString(),
    mimeType: "application/vnd.google-apps.folder",
    parents: [root],
  };
}

