export default async function collect({ previous }, context) {
  const s = previous ?? { cursor: null, count: 0 };
  if (!Number.isInteger(s.count) || s.count < 0) throw Error("Invalid backup progress");
  const r = await context.actions.call("n8n.list_workflows", {
    limit: 1,
    ...(s.cursor ? { cursor: s.cursor } : {}),
  });
  if (
    !Array.isArray(r?.data) ||
    r.data.length > 1 ||
    (r.nextCursor !== null && (typeof r.nextCursor !== "string" || !r.nextCursor))
  )
    throw Error("Invalid n8n workflow page");
  if (r.nextCursor && r.nextCursor === s.cursor) throw Error("Repeated workflow cursor");
  const w = r.data[0];
  if (
    w &&
    (typeof w.id !== "string" ||
      !w.id ||
      typeof w.name !== "string" ||
      !w.name ||
      !Array.isArray(w.nodes) ||
      !w.connections ||
      !w.settings)
  )
    throw Error("Incomplete workflow in backup");
  const count = s.count + (w ? 1 : 0);
  return {
    state: { cursor: r.nextCursor, count },
    more: r.nextCursor !== null,
    hasWorkflow: !!w,
    workflow: w ?? {},
    count,
  };
}

