export default function next({ workflow, folderId }) {
  if (!folderId || typeof workflow?.name !== "string" || !workflow.name)
    throw Error("Missing backup folder or workflow");
  return {
    name: workflow.name + ".json",
    parents: [folderId],
    contentBase64: Buffer.from(JSON.stringify(workflow, null, 2), "utf8").toString("base64"),
  };
}

