export default async function cleanup({ root, newFolderId, count }, context) {
  if (!count) return { ids: [] };
  if (typeof root !== "string" || !root || !newFolderId) throw Error("Missing backup folder");
  const escaped = root.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
  const r = await context.actions.call("googledrive.files.list", {
    q: `'${escaped}' in parents and trashed = false and mimeType = 'application/vnd.google-apps.folder' and name contains 'Workflow Backups '`,
    pageSize: 50,
  });
  if (!Array.isArray(r?.files)) throw Error("Invalid Drive listing");
  const ids = [];
  for (const f of r.files) {
    if (
      typeof f?.id !== "string" ||
      !f.id ||
      typeof f.name !== "string" ||
      typeof f.mimeType !== "string"
    )
      throw Error("Invalid Drive item");
    if (
      f.mimeType === "application/vnd.google-apps.folder" &&
      f.name.startsWith("Workflow Backups ") &&
      f.id.toLowerCase() !== newFolderId.toLowerCase()
    )
      ids.push(f.id);
  }
  return { ids };
}

