export default function next({ ids, previous }) {
  if (!Array.isArray(ids)) throw Error("Invalid cleanup list");
  const index = previous == null ? 0 : previous.index + 1;
  if (!Number.isInteger(index) || index < 0 || index > ids.length)
    throw Error("Invalid cleanup progress");
  return { state: { index }, more: index < ids.length, id: ids[index] ?? "-" };
}
